from collections import Counter

class Solution:
    def bestHand(self, ranks: list[int], suits: list[str]) -> str:
        if len(set(suits)) == 1:
            return 'Flush'
        mx = max(Counter(ranks).values())
        if mx >= 3:
            return 'Three of a Kind'
        if mx == 2:
            return 'Pair'
        return 'High Card'

class Solution {
public:
    std::string bestHand(std::vector<int>& ranks, std::vector<char>& suits) {
        bool flush = true;
        for (int i = 1; i < 5; ++i) {
            if (suits[i] != suits[0]) flush = false;
        }
        if (flush) return "Flush";
        std::unordered_map<int, int> count;
        int mx = 0;
        for (int r : ranks) mx = std::max(mx, ++count[r]);
        if (mx >= 3) return "Three of a Kind";
        if (mx == 2) return "Pair";
        return "High Card";
    }
};

class Solution {
    public String bestHand(int[] ranks, char[] suits) {
        boolean flush = true;
        for (int i = 1; i < 5; ++i) {
            if (suits[i] != suits[0]) flush = false;
        }
        if (flush) return "Flush";
        int[] count = new int[14];
        int mx = 0;
        for (int r : ranks) {
            count[r]++;
            mx = Math.max(mx, count[r]);
        }
        if (mx >= 3) return "Three of a Kind";
        if (mx == 2) return "Pair";
        return "High Card";
    }
}

var bestHand = function(ranks, suits) {
    if (new Set(suits).size === 1) return 'Flush';
    const count = new Map();
    let mx = 0;
    for (const r of ranks) {
        const c = (count.get(r) || 0) + 1;
        count.set(r, c);
        mx = Math.max(mx, c);
    }
    if (mx >= 3) return 'Three of a Kind';
    if (mx === 2) return 'Pair';
    return 'High Card';
};
